const naturalProfiles = NATURAL_COAST_PROFILES.map(samples => {
  // Radialization can jump between two sides of a narrow Earth inlet. Smooth
  // that sampling discontinuity over five degrees while retaining its bay.
  const values = samples.map((_, index) => {
    let sum = 0, weights = 0;
    for (let offset = -15; offset <= 15; offset++) { const weight = Math.exp(-(offset * offset) / 50); sum += samples[(index + offset + samples.length) % samples.length] * weight; weights += weight; }
    return sum / weights;
  });
  return { values, mean: values.reduce((sum, value) => sum + value, 0) / values.length };
});
const round = (value: number) => Number(value.toFixed(6));
const angleDelta = (a: number, b: number) => Math.atan2(Math.sin(a - b), Math.cos(a - b));
const mix = (seed: number, salt: number) => {
  let value = Math.imul(seed ^ Math.imul(salt + 1, 0x9e3779b1), 0x85ebca6b);
  value = Math.imul(value ^ value >>> 13, 0xc2b2ae35);
  return ((value ^ value >>> 16) >>> 0) / 0xffffffff;
};

function split(rect: Rect, axis: "x" | "y", fraction: number): [Rect, Rect] {
  const length = axis === "x" ? rect.width : rect.height;
  const cut = Math.max(1, Math.min(length - 1, Math.round(length * fraction)));
  return axis === "x"
    ? [{ ...rect, width: cut }, { ...rect, x: rect.x + cut, width: rect.width - cut }]
    : [{ ...rect, height: cut }, { ...rect, y: rect.y + cut, height: rect.height - cut }];
}

/** Unequal guillotine partitions produce a large continental plate beside
 * smaller masses, rather than equating the six administrative regions to six
 * identically sized islands. Each tile keeps its original global grid slot. */
function macroPartitions(columns: number, rows: number, seed: number): Rect[] {
  const count = 2 + Math.min(4, Math.floor(mix(seed, 433) * 5));
  const rects: Rect[] = [{ x: 0, y: 0, width: columns, height: rows }];
  while (rects.length < count) {
    let selected = 0;
    for (let index = 1; index < rects.length; index++) if (rects[index].width * rects[index].height > rects[selected].width * rects[selected].height) selected = index;
    const current = rects[selected];
    // The first split separates hemispheres; subsequent splits alternate and
    // use unequal proportions so coastlines don't form latitude bands.
    const latitude = 78 - (current.y + current.height / 2) / rows * 156;
    const physicalWidth = current.width / columns * 352 * Math.max(.35, Math.cos(latitude * RAD));
    const physicalHeight = current.height / rows * 156;
    const preferred = rects.length === 1 || physicalWidth > physicalHeight * (.92 + mix(seed, rects.length) * .35) ? "x" : "y";
    const axis = preferred === "x" ? current.width > 1 ? "x" : "y" : current.height > 1 ? "y" : "x";
    const parts = split(current, axis, .34 + mix(seed, rects.length * 7) * .30);
    rects.splice(selected, 1, ...parts);
  }
  return rects;
}

function grid(input: CoastInputV97) {
  const localColumns = input.columns, localRows = 6 / localColumns;
  const regionColumns = input.layout === "meridians" ? 6 : input.layout === "basins" ? 3 : input.layout === "plates" ? 2 : 1;
  const columns = regionColumns * localColumns, rows = 36 / columns;
  const cells = input.regions.flatMap((region, index) => region.territoryIds.map((id, local) => ({
    id, regionId: region.id,
    x: index % regionColumns * localColumns + local % localColumns,
    y: Math.floor(index / regionColumns) * localRows + Math.floor(local / localColumns),
  })));
  return { columns, rows, cells };
}

function rawRadius(angle: number, phase: number): number {
  const profile = naturalProfiles[Math.floor(phase / TAU * naturalProfiles.length) % naturalProfiles.length];
  const sample = (((angle + phase * .63) / TAU % 1) + 1) % 1 * profile.values.length;
  const index = Math.floor(sample), fraction = sample - index;
  const coast = (profile.values[index] * (1 - fraction) + profile.values[(index + 1) % profile.values.length] * fraction) / profile.mean;
  return .58 * coast + .42 + .025 * Math.sin(angle * 5 + phase) + .012 * Math.sin(angle * 13 - phase * .7);
}

function warpedUV(u: number, v: number, phase: number): WarAtlasPointV95 {
  const strength = (1 - u * u) * (1 - v * v);
  return [u + .085 * strength * v * Math.sin(v * 3.1 + phase), v + .08 * strength * u * Math.sin(u * 3.3 - phase)];
}

function radius(angle: number, macro: Macro): number {
  const x = Math.cos(angle) * macro.maxX, y = Math.sin(angle) * macro.maxY;
  let value = rawRadius(Math.atan2(y, x), macro.phase) / Math.hypot(x, y);
  const rectangularRadius = 1 / Math.max(Math.abs(Math.cos(angle)), Math.abs(Math.sin(angle)));
  // A narrow cape is pinned at each existing inter-continent route. The
  // surrounding gulf remains deep: no route or save changes to fit new art.
  let cape = 0;
  for (const port of macro.ports) cape = Math.max(cape, port.strength * Math.exp(-((angleDelta(angle, port.angle) / .14) ** 2) / 2));
  value += (rectangularRadius - value) * cape;
  return value;
}

function uvAt(x: number, y: number, macro: Macro): WarAtlasPointV95 {
  return warpedUV((x / SAMPLES - macro.x) / macro.width * 2 - 1, (y / SAMPLES - macro.y) / macro.height * 2 - 1, macro.phase);
}
function deformGeography(longitude: number, latitude: number, seed: number): WarAtlasPointV95 {
  const phase = mix(seed, 71) * TAU;
  return [round(longitude + 7 * Math.sin(latitude * RAD * 1.8 + phase) * Math.cos(longitude * RAD / 2)), round(latitude + 3.2 * Math.sin(longitude * RAD + phase) * Math.cos(latitude * RAD))];
}
function pointAt(x: number, y: number, macro: Macro, seed: number, linear = false): WarAtlasPointV95 {
  const [u, v] = uvAt(x, y, macro);
  const radial = Math.hypot(u, v);
  const extent = Math.max(Math.abs(u), Math.abs(v));
  // A radial fractional transform approaches the identity at the center and
  // the authored coast at the boundary. Its radial derivative stays positive,
  // even inside deep bays; coast detail does not pinch internal grid junctions.
  const scale = linear || radial < 1e-12 ? 1 : 1 / (1 + (radial / extent / radius(Math.atan2(v, u), macro) - 1) * extent);
  return deformGeography(macro.longitude + u * scale * macro.lonWidth / 2, macro.latitude - v * scale * macro.latHeight / 2, seed);
}
function boundaryNodes(rect: Rect, step = 1): WarAtlasPointV95[] {
  const left = rect.x * SAMPLES, top = rect.y * SAMPLES, width = rect.width * SAMPLES, height = rect.height * SAMPLES;
  const nodes: WarAtlasPointV95[] = [];
  for (let index = 0; index < width; index += step) nodes.push([left + index, top]);
  for (let index = 0; index < height; index += step) nodes.push([left + width, top + index]);
  for (let index = 0; index < width; index += step) nodes.push([left + width - index, top + height]);
  for (let index = 0; index < height; index += step) nodes.push([left, top + height - index]);
  return nodes;
}
function distance(a: WarAtlasPointV95, b: WarAtlasPointV95) {
  const h = Math.sin((a[1] - b[1]) * RAD / 2) ** 2 + Math.cos(a[1] * RAD) * Math.cos(b[1] * RAD) * Math.sin((a[0] - b[0]) * RAD / 2) ** 2;
  return 2 * Math.asin(Math.sqrt(Math.min(1, h))) / RAD;
}

export function coastGeographyV97(input: CoastInputV97): { regions: WarAtlasRegionV95[]; territories: WarAtlasTerritoryV95[]; landmasses: WarLandmassV97[] } {
  const { columns, rows, cells } = grid(input);
  const partitions = macroPartitions(columns, rows, input.seed);
  const macros: Macro[] = partitions.map((rect, index) => {
    const phase = mix(input.seed, index * 19) * TAU;
    let maxX = 0, maxY = 0;
    for (let sample = 0; sample < 1440; sample++) { const angle = sample / 1440 * TAU, r = rawRadius(angle, phase); maxX = Math.max(maxX, Math.abs(r * Math.cos(angle))); maxY = Math.max(maxY, Math.abs(r * Math.sin(angle))); }
    return { ...rect, id: `${input.id}-land-${index + 1}`, cells: cells.filter(cell => cell.x >= rect.x && cell.x < rect.x + rect.width && cell.y >= rect.y && cell.y < rect.y + rect.height), phase, ports: [], longitude: -176 + (rect.x + rect.width / 2) / columns * 352, latitude: 78 - (rect.y + rect.height / 2) / rows * 156, lonWidth: rect.width / columns * 352 - 3.2, latHeight: rect.height / rows * 156 - 3.2, maxX: maxX * 1.005, maxY: maxY * 1.005 };
  });
  const macroByCell = new Map(macros.flatMap(macro => macro.cells.map(cell => [cell.id, macro] as const)));
  const cellById = new Map(cells.map(cell => [cell.id, cell]));
  for (const definition of input.definitions) for (const neighborId of definition.neighbors) {
    if (definition.id >= neighborId) continue;
    const a = macroByCell.get(definition.id)!, b = macroByCell.get(neighborId)!;
    if (a === b) continue;
    const fullA = boundaryNodes({ ...cellById.get(definition.id)!, width: 1, height: 1 });
    const fullB = boundaryNodes({ ...cellById.get(neighborId)!, width: 1, height: 1 });
    const coastA = fullA.filter((_, index) => index % 2 === 0).map(([x, y]) => pointAt(x, y, a, input.seed));
    const coastB = fullB.filter((_, index) => index % 2 === 0).map(([x, y]) => pointAt(x, y, b, input.seed));
    if (coastA.some(first => coastB.some(second => distance(first, second) <= 19.5))) continue;
    const nodesA = fullA.filter((_, index) => index % 4 === 0);
    const nodesB = fullB.filter((_, index) => index % 4 === 0);
    let shortest = Infinity, portA = nodesA[0], portB = nodesB[0];
    for (const first of nodesA) for (const second of nodesB) {
      const length = distance(pointAt(first[0], first[1], a, input.seed, true), pointAt(second[0], second[1], b, input.seed, true));
      if (length < shortest) { shortest = length; portA = first; portB = second; }
    }
    const add = (macro: Macro, port: WarAtlasPointV95) => { const [u, v] = uvAt(port[0], port[1], macro); const cape = { angle: Math.atan2(v, u), strength: 0 }; macro.ports.push(cape); return cape; };
    const capeA = add(a, portA), capeB = add(b, portB);
    let low = 0, high = 1;
    for (let iteration = 0; iteration < 14; iteration++) {
      const strength = (low + high) / 2;
      capeA.strength = strength; capeB.strength = strength;
      if (distance(pointAt(portA[0], portA[1], a, input.seed), pointAt(portB[0], portB[1], b, input.seed)) > 19.5) low = strength;
      else high = strength;
    }
    capeA.strength = high; capeB.strength = high;
  }
  const territories: WarAtlasTerritoryV95[] = cells.map(cell => {
    const macro = macroByCell.get(cell.id)!;
    const marker = pointAt((cell.x + .5) * SAMPLES, (cell.y + .5) * SAMPLES, macro, input.seed);
    return { id: cell.id, regionId: cell.regionId, landmassId: macro.id, longitude: marker[0], latitude: marker[1], points: boundaryNodes({ ...cell, width: 1, height: 1 }).map(([x, y]) => pointAt(x, y, macro, input.seed)) };
  });
  const landmasses = macros.map(macro => {
    const center = pointAt((macro.x + macro.width / 2) * SAMPLES, (macro.y + macro.height / 2) * SAMPLES, macro, input.seed);
    return { id: macro.id, territoryIds: macro.cells.map(cell => cell.id), longitude: center[0], latitude: center[1], points: boundaryNodes(macro).map(([x, y]) => pointAt(x, y, macro, input.seed)) };
  });
  const regions = input.regions.map(region => {
    const members = territories.filter(territory => territory.regionId === region.id);
    // An administrative region can span a strait; center its label on one of
    // its real territories instead of placing it in the sea between masses.
    const marker = members[Math.floor(members.length / 2)];
    return { ...region, territoryIds: [...region.territoryIds], longitude: marker.longitude, latitude: marker.latitude };
  });
  return { regions, territories, landmasses };
}
